const slides = ref([
    {
        bg: '#18a058',
        text: '色块 1 · primary'
    } as UTSJSONObject,
    {
        bg: '#2080f0',
        text: '色块 2 · info'
    } as UTSJSONObject,
    {
        bg: '#f0a020',
        text: '色块 3 · warning'
    } as UTSJSONObject
] as UTSJSONObject[])

const current = ref(0)

function prev() {
    if (current.value <= 0) {
        current.value = slides.value.length - 1
        return
    }
    current.value = current.value - 1
}

function next() {
    if (current.value >= slides.value.length - 1) {
        current.value = 0
        return
    }
    current.value = current.value + 1
}
